<script lang="ts">import {statusClass,statusText,type AiccStatus} from '../lib/workflow';export let stages:[string,string][]=[];export let current=0;export let blocked=false;</script>
<div class="workflow-timeline" data-testid="workflow-timeline">{#each stages as stage,i}<div class:current={i===current} class:completed={i<current} class:blocked={blocked&&i===current} class="workflow-stage"><span class="stage-dot {statusClass(blocked&&i===current?'BLOCKED':i<current?'COMPLETE':i===current?'IN_PROGRESS':'NOT_STARTED' as AiccStatus)}">{i<current?'✓':i+1}</span><div><strong>{stage[1]}</strong><small>{stage[0]}</small><em>{i<current?'已完成':i===current?'进行中':'未开始'}</em></div></div>{/each}</div>
